/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  random,
} from '../remotionShim';
// Schema Definition


export type AlgorithmicFractureProps = Record<string, any>;

const AlgorithmicFracture: React.FC<AlgorithmicFractureProps> = ({
  backgroundColor = "#030712", // Deep Navy Blue / Dark Gray
  pathColor = "#00F0FF", // Glowing Cyan
  particleColors = ["#FF3B30", "#FF9500", "#FF2D55"], // Red, Orange, Pinkish red
  glitchIntensity = 0.8,
  transparentBackground = false,
  durationInSeconds = 8,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Timing constants
  const totalFrames = durationInSeconds * fps;
  const fractureFrame = Math.floor(totalFrames * 0.45); // Fractures at 45% of the animation
  const glitchStartFrame = Math.floor(fractureFrame - fps * 1.5); // Starts glitching 1.5s before fracture
  const pathDrawDuration = fps * 2; // Takes 2s to draw the path

  // Background handling
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // --- Geometry & Path Generation ---
  // Define 5 points for a zig-zag high-tech path (bottom to top)
  const points = useMemo(() => {
    return [
      { x: width * 0.15, y: height * 0.9 },
      { x: width * 0.65, y: height * 0.7 },
      { x: width * 0.25, y: height * 0.45 },
      { x: width * 0.85, y: height * 0.25 },
      { x: width * 0.4, y: height * 0.05 },
    ];
  }, [width, height]);

  // Pre-calculate path segments for sequential drawing
  const segments = useMemo(() => {
    const segs = [];
    const framesPerSegment = Math.floor(pathDrawDuration / (points.length - 1));
    for (let i = 0; i < points.length - 1; i++) {
      segs.push({
        p1: points[i],
        p2: points[i + 1],
        startFrame: i * framesPerSegment,
        endFrame: (i + 1) * framesPerSegment,
      });
    }
    return segs;
  }, [points, pathDrawDuration]);

  // --- Particle System Generation ---
  const particles = useMemo(() => {
    const pCount = 300; // Total particles representing "loss and failure"
    return Array.from({ length: pCount }).map((_, i) => {
      // Distribute particles randomly along the segments
      const segIndex = Math.floor(random(`seg-${i}`) * segments.length);
      const seg = segments[segIndex];
      const t = random(`pos-${i}`);

      // Base position on the line
      const baseX = seg.p1.x + (seg.p2.x - seg.p1.x) * t;
      const baseY = seg.p1.y + (seg.p2.y - seg.p1.y) * t;

      // Add cluster spread (thicker glowing line effect)
      const startX = baseX + (random(`spreadX-${i}`) - 0.5) * 50;
      const startY = baseY + (random(`spreadY-${i}`) - 0.5) * 50;

      // Explosion velocities (chaotic, mostly downward due to gravity later)
      const vx = (random(`vx-${i}`) - 0.5) * 40; // Horizontal drift
      const vy = (random(`vy-${i}`) - 0.5) * 30 - 15; // Initial upward/outward burst

      // Color assignment from the user's array
      const colorIdx = Math.floor(random(`color-${i}`) * particleColors.length);
      const color = particleColors[colorIdx];

      // Physical properties
      const size = random(`size-${i}`) * 6 + 2;
      const rotationSpeed = (random(`rot-${i}`) - 0.5) * 20;

      return { startX, startY, vx, vy, color, size, rotationSpeed };
    });
  }, [segments, particleColors]);

  // --- Animation States ---
  const isPreFracture = frame <= fractureFrame;
  const isGlitching = frame >= glitchStartFrame && isPreFracture;

  // Glitch Effect Calculations
  const shakeX = isGlitching
    ? (random(`shakeX-${frame}`) - 0.5) * 30 * glitchIntensity
    : 0;
  const shakeY = isGlitching
    ? (random(`shakeY-${frame}`) - 0.5) * 20 * glitchIntensity
    : 0;
  
  // Opacity of the main path
  const pathOpacity = isPreFracture
    ? isGlitching && random(`flicker-${frame}`) > 0.7
      ? 0.3 // Flicker effect
      : 1
    : 0;

  // Cinematic Camera Movement (slow scale and drift)
  const cameraScale = interpolate(frame, [0, totalFrames], [1, 1.15]);
  const cameraRotateX = interpolate(frame, [0, totalFrames], [5, -5]);
  const cameraRotateY = interpolate(frame, [0, totalFrames], [-3, 3]);

  // Background Grid Properties
  const gridSize = width * 0.1;
  const gridOpacity = interpolate(
    frame,
    [glitchStartFrame, fractureFrame],
    [0.15, 0.05],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        perspective: "1000px",
        overflow: "hidden",
      }}
    >
      {/* High-Tech Background Grid */}
      <div
        style={{
          position: "absolute",
          top: "-50%",
          left: "-50%",
          width: "200%",
          height: "200%",
          backgroundImage: `
            linear-gradient(to right, ${pathColor} 1px, transparent 1px),
            linear-gradient(to bottom, ${pathColor} 1px, transparent 1px)
          `,
          backgroundSize: `${gridSize}px ${gridSize}px`,
          opacity: gridOpacity,
          transform: `translateZ(-500px) rotateX(60deg) translateY(${
            (frame % (fps * 2)) * 2
          }px)`,
          transition: "none",
        }}
      />

      {/* Main 3D Container */}
      <AbsoluteFill
        style={{
          transform: `scale(${cameraScale}) rotateX(${cameraRotateX}deg) rotateY(${cameraRotateY}deg) translate(${shakeX}px, ${shakeY}px)`,
          transformStyle: "preserve-3d",
          transition: "none",
        }}
      >
        {/* The Clean Geometric Path (Pre-Fracture) */}
        {isPreFracture && (
          <svg
            width={width}
            height={height}
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              opacity: pathOpacity,
              filter: `drop-shadow(0 0 15px ${pathColor}) drop-shadow(0 0 30px ${pathColor})`,
              transition: "none",
            }}
          >
            {segments.map((seg, i) => {
              // Calculate how much of this specific segment is drawn
              const drawProgress = interpolate(
                frame,
                [seg.startFrame, seg.endFrame],
                [0, 1],
                { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
              );

              if (drawProgress === 0) return null;

              const currentX = seg.p1.x + (seg.p2.x - seg.p1.x) * drawProgress;
              const currentY = seg.p1.y + (seg.p2.y - seg.p1.y) * drawProgress;

              // Glitch split effect (RGB shift) during glitch phase
              const rgbShift =
                isGlitching && random(`rgb-${frame}-${i}`) > 0.5
                  ? (random(`shift-${frame}`) - 0.5) * 40 * glitchIntensity
                  : 0;

              return (
                <g key={`seg-${i}`}>
                  {/* Chromatic aberration layers */}
                  {rgbShift !== 0 && (
                    <line
                      x1={seg.p1.x - rgbShift}
                      y1={seg.p1.y}
                      x2={currentX - rgbShift}
                      y2={currentY}
                      stroke="red"
                      strokeWidth={8}
                      strokeLinecap="round"
                      opacity={0.5}
                    />
                  )}
                  {rgbShift !== 0 && (
                    <line
                      x1={seg.p1.x + rgbShift}
                      y1={seg.p1.y}
                      x2={currentX + rgbShift}
                      y2={currentY}
                      stroke="blue"
                      strokeWidth={8}
                      strokeLinecap="round"
                      opacity={0.5}
                    />
                  )}
                  {/* Main Line */}
                  <line
                    x1={seg.p1.x}
                    y1={seg.p1.y}
                    x2={currentX}
                    y2={currentY}
                    stroke={pathColor}
                    strokeWidth={8}
                    strokeLinecap="round"
                  />
                  {/* Glowing Node at current tip */}
                  <circle
                    cx={currentX}
                    cy={currentY}
                    r={drawProgress < 1 ? 10 : 0}
                    fill="#FFFFFF"
                  />
                </g>
              );
            })}
          </svg>
        )}

        {/* The Chaotic Digital Noise / Particles (Post-Fracture) */}
        {!isPreFracture && (
          <AbsoluteFill style={{ transition: "none" }}>
            {particles.map((p, i) => {
              const pFrame = frame - fractureFrame;
              
              // Gravity effect (accelerating downwards)
              const gravity = 1.5;
              
              // Calculate current position
              const curX = p.startX + p.vx * pFrame;
              const curY = p.startY + p.vy * pFrame + 0.5 * gravity * Math.pow(pFrame, 2);
              const rotation = p.rotationSpeed * pFrame;

              // Particles fade out towards the end
              const pOpacity = interpolate(
                pFrame,
                [0, 10, totalFrames - fractureFrame - 20, totalFrames - fractureFrame],
                [0, 1, 1, 0],
                { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
              );

              // Don't render if completely offscreen to save performance
              if (curY > height + 100) return null;

              return (
                <div
                  key={`particle-${i}`}
                  style={{
                    position: "absolute",
                    left: 0,
                    top: 0,
                    width: p.size,
                    height: p.size * (random(`stretch-${i}`) > 0.5 ? 3 : 1), // Some particles stretch like digital rain
                    backgroundColor: p.color,
                    opacity: pOpacity,
                    boxShadow: `0 0 ${p.size * 2}px ${p.color}`,
                    transform: `translate(${curX}px, ${curY}px) rotate(${rotation}deg)`,
                    transition: "none",
                  }}
                />
              );
            })}
          </AbsoluteFill>
        )}

        {/* Digital Static Noise Overlay */}
        {glitchIntensity > 0 && (
          <AbsoluteFill
            style={{
              opacity: interpolate(
                frame,
                [glitchStartFrame, fractureFrame, fractureFrame + 15],
                [0, 0.4 * glitchIntensity, 0],
                { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
              ),
              mixBlendMode: "overlay",
              pointerEvents: "none",
              transition: "none",
            }}
          >
            {/* Generate random horizontal blocks of noise for the static glitch look */}
            {Array.from({ length: 15 }).map((_, i) => {
              const top = random(`noise-y-${frame}-${i}`) * 100;
              const heightPct = random(`noise-h-${frame}-${i}`) * 5 + 1;
              const opacity = random(`noise-o-${frame}-${i}`) * 0.8;
              
              return (
                <div
                  key={`noise-${i}`}
                  style={{
                    position: "absolute",
                    top: `${top}%`,
                    left: 0,
                    width: "100%",
                    height: `${heightPct}%`,
                    backgroundColor: "#FFFFFF",
                    opacity: opacity,
                    transition: "none",
                  }}
                />
              );
            })}
          </AbsoluteFill>
        )}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default AlgorithmicFracture;